#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 63
#define MAX_ROMAN_VALUE 3999

static const struct {
    const char *sym;
    int value;
} roman_map[] = {
    {"M",  1000},
    {"CM",  900},
    {"D",   500},
    {"CD",  400},
    {"C",   100},
    {"XC",   90},
    {"L",    50},
    {"XL",   40},
    {"X",    10},
    {"IX",    9},
    {"V",     5},
    {"IV",    4},
    {"I",     1},
    {NULL,    0}
};

static int roman_to_int(const char *s)
{
    int total = 0;
    int i = 0;
    int repeat = 0;
    char last = 0;
    while (s[i]) {
        int matched = 0;
        int value = 0;
        for (int k = 0; roman_map[k].sym != NULL; ++k) {
            size_t len = strlen(roman_map[k].sym);
            if (strncmp(s + i, roman_map[k].sym, len) == 0) {
                matched = (int)len;
                value = roman_map[k].value;
                break;
            }
        }
        if (!matched) return -1; // illegal character
        char c = s[i];
        if (c == last) {
            ++repeat;
            if (c == 'V' || c == 'L' || c == 'D') return -1;
            if (repeat > 2) return -1; // more than three repeats
        } else {
            repeat = 0;
        }
        last = c;
        total += value;
        i += matched;
    }
    return total;
}

static void int_to_roman(int value, char *out, size_t outsize)
{
    size_t pos = 0;
    for (int i = 0; roman_map[i].sym != NULL; ++i) {
        while (value >= roman_map[i].value) {
            size_t len = strlen(roman_map[i].sym);
            if (pos + len + 1 > outsize) return; // safety
            memcpy(out + pos, roman_map[i].sym, len);
            pos += len;
            value -= roman_map[i].value;
        }
    }
    out[pos] = '\0';
}

static void strtoupper(char *s)
{
    for (; *s; ++s) *s = (char)toupper((unsigned char)*s);
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }
    char input[MAX_INPUT_LEN + 2];
    strncpy(input, argv[1], sizeof(input) - 1);
    input[sizeof(input) - 1] = '\0';
    size_t len = strlen(input);
    if (len == 0 || len > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }
    strtoupper(input);
    int value = roman_to_int(input);
    if (value <= 0 || value > MAX_ROMAN_VALUE) {
        puts("INVALID");
        return 0;
    }
    char canonical[64];
    int_to_roman(value, canonical, sizeof(canonical));
    if (strcmp(input, canonical) != 0) {
        puts("INVALID");
        return 0;
    }
    printf("%d\n", value);
    return 0;
}
